namespace CX.Alloy;

/// <summary>
/// The renderer's own slash commands, every one generated by its knob group's declaration (ADR 0025).
/// Registration happens ahead of every renderer stand-down, so <c>/alloy</c> -- which reports which renderer
/// is running and why -- exists even in a session that owns nothing.
/// </summary>
internal static class RenderCommands
{
    /// <summary>Called once from <see cref="AlloyRenderer"/>'s Initialize, before any early return.</summary>
    internal static void Register()
    {
        // ADR 0025: every Graphics command is generated by its group's declaration; touching the classes here
        // is what makes them declare now, on this thread, rather than on the render thread at the first draw.
        // Renderer first: every other group names alloy.enabled as its parent.
        _ = Renderer.G;
        _ = Lighting.G;
        _ = Shadows.G;
        _ = Grass.G; _ = Post.G; _ = Ao.G; _ = Lod.G; _ = Fog.G; _ = VolumetricFog.G; _ = Water.G; _ = Effects.G; _ = Particles.G; _ = Dangly.G; _ = Weather.G; _ = Lightmap.G;
        _ = Db.DbTiles.G;   // CX-116: /dbtiles reports the DB tile build and drives its live comparison
    }
}
